import { Table, Password2Column, GenericColumn, StringColumn } from '../../db'

export const sys_auth_profile_basic = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    extends: 'sys_auth_profile',
    label: 'Basic Auth Configuration',
    name: 'sys_auth_profile_basic',
    schema: {
        password: Password2Column({
            attributes: {
                edge_encryption_enabled: true,
                is_legacy_password2: true,
                no_data_replicate: true,
            },
            label: [
                {
                    hint: 'The password used to authenticate the HTTP request when this Basic authentication profile is enabled',
                    label: 'Password',
                    plural: 'Passwords',
                },
            ],
            mandatory: true,
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        username: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: [
                {
                    hint: 'The username used to authenticate the HTTP request when this Basic authentication profile is enabled',
                    label: 'Username',
                    plural: 'Usernames',
                },
            ],
            mandatory: true,
            maxLength: 80,
        }),
    },
    textIndex: true,
})
